import { inject, Injectable } from '@angular/core';
import { DataApiService } from '../../../services/data-api.service';
import { MensajesHttpService } from '../../../utils/mensajesHttp/mensajes-http.service';
import { BehaviorSubject, EMPTY, Observable } from 'rxjs';
import { DataApi } from '../../../Model/dataApi';
import { catchError, tap } from 'rxjs/operators';
import { HttpErrorResponse } from '@angular/common/http';

@Injectable({
  providedIn: 'root',
})

export class ClientesFacadeService {

  private dataApi = inject(DataApiService);
  private _mensajesHttp = inject(MensajesHttpService);

  private Cargando$ = new BehaviorSubject<boolean>(false);
  public responseCargando$: Observable<boolean> = this.Cargando$.asObservable();

  private Clientes$ = new BehaviorSubject<any[]>([]);
  public responseClientes$: Observable<any[]> = this.Clientes$.asObservable();

  private TipoIdentificacion$ = new BehaviorSubject<any[]>([]);
  public responseTipoIdentificacion$: Observable<any[]> = this.TipoIdentificacion$.asObservable();

  private TipoCliente$ = new BehaviorSubject<any[]>([]);
  public responseTipoCliente$: Observable<any[]> = this.TipoCliente$.asObservable();

  private EstadoClientes$ = new BehaviorSubject<any[]>([]);
  public responseEstadoClientes$: Observable<any[]> = this.EstadoClientes$.asObservable();

  constructor() { }


  MostrarClientes(params: any) {
    this.Cargando$.next(true);
    this.Clientes$.next([]);
    const request$ = this.dataApi.GetDataApi(`administracion/v1/clientes/`, params).pipe(
      tap((result: DataApi | any) => {
        this.Cargando$.next(false);
        this.Clientes$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.Clientes$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar los Clientes', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  InsertarClientes(params: any, respuesta) {
    this.Cargando$.next(true);
    const request$ = this.dataApi.PostDataApi(`administracion/v1/clientes/`, params).pipe(
      tap((result: DataApi | any) => {
        respuesta(result);

      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al insertar el Cliente', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  ActualizarClientes(params: any, respuesta) {
    this.Cargando$.next(true);
    const request$ = this.dataApi.PutDataApi(`administracion/v1/clientes/`, params).pipe(
      tap((result: DataApi | any) => {
        respuesta(result);

      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al actualizar el Cliente', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }
  MostrarTipoIdentificacion(params: any) {
    this.Cargando$.next(true);
    this.TipoIdentificacion$.next([]);
    const request$ = this.dataApi.GetDataApi(`personas/tipoIdentificacion/`, params).pipe(
      tap((result: DataApi | any) => {
        this.Cargando$.next(false);
        this.TipoIdentificacion$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.TipoIdentificacion$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar los tipos de identificación', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  MostrarTipoCliente(params: any) {
    this.Cargando$.next(true);
    this.TipoCliente$.next([]);
    const request$ = this.dataApi.GetDataApi(`administracion/v1/tipo-cliente/`, params).pipe(
      tap((result: DataApi | any) => {
        this.Cargando$.next(false);
        this.TipoCliente$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.TipoCliente$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar los tipos de cliente', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  MostrarEstadoCliente(params: any) {
    this.Cargando$.next(true);
    this.EstadoClientes$.next([]);
    const request$ = this.dataApi.GetDataApi(`administracion/v1/estado-cliente/`, params).pipe(
      tap((result: DataApi | any) => {
        this.Cargando$.next(false);
        this.EstadoClientes$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.EstadoClientes$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar los tipos de estados de clientes', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

}
