import { Component, inject, OnInit } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import Swal from 'sweetalert2';
import { TipoContactoFacadeService } from './tipo-contacto-facade.service';
import { PageEvent } from '@angular/material/paginator';
import { MatDialog } from '@angular/material/dialog';
import { ToastrServiceLocal } from '../../../services/toast/toastr.service';

@Component({
  selector: 'app-tipo-contacto',
  templateUrl: './tipo-contacto.component.html',
  styleUrls: ['./tipo-contacto.component.css'],
  standalone: false
})
export class TipoContactoComponent implements OnInit {

  public tipoContactoFacade = inject(TipoContactoFacadeService);
  public dialog = inject(MatDialog);
  public toast = inject(ToastrServiceLocal);
  public buscar = new FormControl('');
  public formTipoContacto: FormGroup;
  public pageSize = 10;
  public page = 0;
  public pageEvent: PageEvent;
  public pageIndex: number = 0;
  public desde = 0;
  public hasta = 10;

  constructor() {
    this.tipoContactoFacade.MostrarTipoContacto('0');
  }

  ngOnInit(): void {
  }

  openDialog(template, item?) {
    this.formTipoContacto = new FormGroup({
      id: new FormControl(item?.Id || 0),
      tipoContacto: new FormControl(item?.TipoContacto || '', [Validators.required]),
      idEstado: new FormControl(item?.IdEstado || ''),
    });

    const dialogRef = this.dialog.open(template, {
      panelClass: "app-full-bleed-dialog", //Agregar una clase ccs al dialogo,
      width: '40%',
      disableClose: true
    });

  }

  Guardar() {
    if (this.formTipoContacto.invalid) {
      this.toast.mensajeWarning('Es requerido ingresar los campos marcados como obligatorios', '');
      this.formTipoContacto.markAllAsTouched();
      return;
    }

    if (this.formTipoContacto.get('id').value === 0) {
      this.tipoContactoFacade.InsertarTipoContacto(this.formTipoContacto.value, (respuesta) => {
        if (respuesta.hasError === false) {
          this.tipoContactoFacade.MostrarTipoContacto('0');
          this.dialog.closeAll();
        }
      });
    } else {
      this.tipoContactoFacade.ActualizarTipoContacto(this.formTipoContacto.value, (respuesta) => {
        if (respuesta.hasError === false) {
          this.tipoContactoFacade.MostrarTipoContacto('0');
          this.dialog.closeAll();
        }
      });
    }
  }

  Eliminar(params) {
    Swal.fire({
      title: "Confirmación",
      html: ` <p> ¿Esta seguro quiere inhabilitar el tipo de contacto <b>${params.TipoContacto}</b>? </p>`,
      icon: "question",
      showCancelButton: true,
      confirmButtonColor: "#003399",
      cancelButtonColor: "#d33",
      confirmButtonText: "Confirmar",
      cancelButtonText: "Cancelar",
    }).then((result) => {
      if (result.isConfirmed) {
        this.tipoContactoFacade.EliminarTipoContacto(params.Id, (respuesta) => {
          this.tipoContactoFacade.MostrarTipoContacto("0");

        })
      }
    });
  }

  next(event: PageEvent) {

    if (event.pageIndex === this.pageIndex + 1) {
      this.desde = this.desde + this.pageSize;
      this.hasta = this.hasta + this.pageSize;
    }
    else if (event.pageIndex === this.pageIndex - 1) {
      this.desde = this.desde - this.pageSize;
      this.hasta = this.hasta - this.pageSize;
    }
    this.pageIndex = event.pageIndex;
  }

}
